}

Map<String, Object?> _run({
  required Object id,
  required String sha,
  String? tree,
  String conclusion = 'success',
}) => {
  'database_id': id,
  'head_sha': sha,
  'tree_sha': tree,
  'conclusion': conclusion,
};

