      'what was validated)', () async {
    final code = await runGuard([
      _run(id: 11, sha: 'ahead1', tree: 'newertree'),
      _run(id: 12, sha: 'ahead2', tree: 'evennewer'),
    ]);
    expect(code, 3);
  });

