    final code = await runGuard([
      _run(id: 11, sha: 'nope1', tree: 'nope'),
      _run(id: 12, sha: 'nope2', tree: _tree),
      _run(id: 13, sha: 'nope3', conclusion: 'failure', tree: _tree),
    ]);
    expect(
      code,
      0,
      reason:
