/// and alarm on everything else — a failed validation, a tag/push-event
/// run, a stale-only match, or no dispatch at all.
library;

import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';

const _script = 'scripts/sm_merge_guard.py';

