const _sha = 'aaaabbbbccccdddd';
const _tree = 'tree1111';
const _subject = 'gh-999 some story (#1000)';

Future<int> runGuard(
  List<Map<String, Object?>> runs, {
  String subject = [REDACTED:Certificate DN],
  String sha = _sha,
